public int binarySearch(int[] arr, int target) {
  int left = 0;
  int right = arr.length;
  while (left < right) {
    int mid = (left + right) / 2;
    if (arr[mid] == target) return mid;
    if (arr[mid] < target) left = mid;
    else right = mid;
  }
  return -1;
}

